// Tauri plugin command surface. These names become the
// `plugin:mpv|<cmd>` invoke targets and drive the autogenerated
// `permissions/autogenerated/commands/*.toml` (one allow-/deny- pair
// each) plus the permission schema.
const COMMANDS: &[&str] = &[
    "attach",
    "set_bounds",
    "load",
    "play",
    "pause",
    "seek",
    "set_property_str",
    "set_property_f64",
    "set_property_bool",
    "command",
    "stop",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).build();

    // Bake the wall-clock build time into the binary. The running app
    // surfaces it (debug dump + panel badge) so we can tell at a glance
    // whether the NATIVE binary was actually recompiled: a webview reload
    // picks up new JS but NOT new Rust, and a stale build time is the
    // unambiguous tell. Cargo reruns this script whenever a source file
    // changes (no rerun-if-changed is emitted), so the stamp tracks every
    // real rebuild and stays put when nothing changed.
    let build_unix = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    println!("cargo:rustc-env=MPV_PLUGIN_BUILD_UNIX={build_unix}");

    // libmpv2-sys emits `-lmpv` but no link-search path. On macOS the
    // Homebrew dylib lives at /opt/homebrew/lib which isn't on cc's
    // default search path, so the link step fails with
    // "library 'mpv' not found". Probe the well-known locations and
    // append the first that contains libmpv. These directives propagate
    // to the consuming app's final binary link step, so a consumer that
    // depends on this plugin links libmpv without touching its own
    // build.rs. (Dev-time points at the system Homebrew install; a
    // distributable .app still needs the consumer to bundle libmpv +
    // fix the rpath — a pre-existing concern, documented in README.)
    #[cfg(target_os = "macos")]
    {
        let candidates = [
            "/opt/homebrew/lib", // Apple Silicon Homebrew
            "/usr/local/lib",    // Intel Homebrew / system install
        ];
        for path in candidates {
            if std::path::Path::new(&format!("{path}/libmpv.dylib")).exists() {
                println!("cargo:rustc-link-search=native={path}");
                println!("cargo:rustc-link-arg=-Wl,-rpath,{path}");
                break;
            }
        }
    }

    // Windows support is experimental. Do not redistribute unreviewed DLLs;
    // an explicit external libmpv SDK is required for cross-platform work.
    println!("cargo:rerun-if-env-changed=MPV_LIB_DIR");
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        let dir = std::env::var("MPV_LIB_DIR")
            .expect("Set MPV_LIB_DIR to your external libmpv SDK directory");
        println!("cargo:rustc-link-search=native={dir}");
    }
}
